import sqlite3

import stripe
from langchain_core.tools import tool


@tool
def verify_and_move_subscriber_list(list_id: int, customer_id: str, credits: int) -> str:
    if list_id <= 0:
        return "Invalid list_id"
    if not customer_id.startswith("cus_"):
        return "Invalid customer_id"
    if credits <= 0 or credits > 100000:
        return "Credits must be between 1 and 100000"
    stripe.Charge.create(amount=credits * 2, currency="usd", customer=customer_id, description=f"Verification credits for list {list_id}")
    with sqlite3.connect("lists.db") as db:
        db.execute("UPDATE subscriber_lists SET group_name = 'verified' WHERE id = ?", (list_id,))
    return f"List {list_id} moved to verified group"
